class PokeAPI{constructor(){this.baseURL="https://pokeapi.co/api/v2/",this.cache=new Map,this.cacheTimeout=3e5}clearExpiredCache(){var t,e,a=Date.now();for([t,e]of this.cache.entries())e.timestamp&&a-e.timestamp>this.cacheTimeout&&this.cache.delete(t)}async fetchPokemonList(t=20,e=0){this.clearExpiredCache();var a=`pokemon-list-${t}-`+e,o=this.cache.get(a);if(o&&Date.now()-o.timestamp<this.cacheTimeout)return o.data;o=this.baseURL+`pokemon?limit=${t}&offset=`+e;try{var s,r=await fetch(o);if(r.ok)return s=await r.json(),this.cache.set(a,{data:s,timestamp:Date.now()}),s;throw new Error("Erro ao buscar lista de Pokémons: "+r.status)}catch(t){throw console.error("Erro ao buscar lista de Pokémons:",t),t}}async fetchPokemon(t){t="string"==typeof t&&t.startsWith("http")?t:this.baseURL+"pokemon/"+t,t=await fetch(t);if(t.ok)return t.json();throw new Error("Erro ao buscar Pokémon")}async fetchPokemonTypes(){var t=await fetch(this.baseURL+"type");if(t.ok)return(await t.json()).results;throw new Error("Erro ao buscar tipos")}async fetchPokemonSpecies(t){var e="species-"+t,a=this.cache.get(e);if(a&&Date.now()-a.timestamp<this.cacheTimeout)return a.data;a=this.baseURL+"pokemon-species/"+t;try{var o,s=await fetch(a);if(s.ok)return o=await s.json(),this.cache.set(e,{data:o,timestamp:Date.now()}),o;throw new Error("Erro ao buscar espécie: "+s.status)}catch(t){return console.error("Erro ao buscar espécie:",t),null}}}